graphql.query:
query GetRecipes($search: String, $tag: String, $difficulty: Difficulty) {
  recipes(search: $search, tag: $tag, difficulty: $difficulty) {
    id
    title
    emoji
    difficulty
    prepTimeMinutes
    tags
    isFavorite
  }
}

query GetRecipe($id: ID!) {
  recipe(id: $id) {
    id
    title
    description
    emoji
    prepTimeMinutes
    difficulty
    tags
    isFavorite
    ingredients {
      id
      name
      quantity
    }
    steps
    createdAt
    updatedAt
  }
}

mutation CreateRecipe($input: RecipeInput!) {
  createRecipe(input: $input) {
    id
    title
    difficulty
    isFavorite
  }
}

